"use strict";
const names = ["ada", "grace", "linus"];
class Version {
  constructor(text) {
    const [major, minor] = text.split(".").map(Number);
    this.major = major;
    this.minor = minor;
    this.hits = 0;
    this.label = "v";
  }
  toString() {
    return `${this.major}.${this.minor}`;
  }
}
class Money {
  constructor(cents) {
    this.cents = cents;
  }
  valueOf() {
    return this.cents;
  }
}
class Tagged {
  [Symbol.toPrimitive](hint) {
    return hint === "number" ? 42 : `tagged:${hint}`;
  }
}
exports.Version = Version;
exports.Money = Money;
exports.Tagged = Tagged;
exports.list = () => names;
exports.fresh = () => names.map((n) => n.toUpperCase());
exports.table = () => new Map([["a", 1], ["b", 2]]);
exports.count = (xs) => xs.length;
exports.join = (...parts) => parts.join("+");
exports.push = (name) => { names.push(name); };
exports.maybe = (on) => (on ? new Version("1.2") : undefined);
exports.config = { nested: { depth: 3 }, retries: 1, name: "cfg" };
exports.optional = (on) => (on ? { nested: { depth: 7 } } : null);
exports.helper = { greet: (who) => `hi ${who}` };
